#include "godot_store_kit.h"

#import <Foundation/Foundation.h>

// Generated by swiftc from StoreKitBridge.swift (see build.sh).
#import "CrownroadStoreKit-Swift.h"

GodotStoreKit *GodotStoreKit::instance = nullptr;
static CRStoreKitBridge *bridge = nil;

static NSString *to_ns_string(const String &p_string) {
	return [NSString stringWithUTF8String:p_string.utf8().get_data()];
}

static Variant to_variant(id p_value) {
	if (p_value == nil || p_value == [NSNull null]) {
		return Variant();
	}
	if ([p_value isKindOfClass:[NSString class]]) {
		return String::utf8([(NSString *)p_value UTF8String]);
	}
	if ([p_value isKindOfClass:[NSNumber class]]) {
		NSNumber *number = p_value;
		if (CFGetTypeID((__bridge CFTypeRef)number) == CFBooleanGetTypeID()) {
			return (bool)number.boolValue;
		}
		if (CFNumberIsFloatType((__bridge CFNumberRef)number)) {
			return number.doubleValue;
		}
		return (int64_t)number.longLongValue;
	}
	if ([p_value isKindOfClass:[NSArray class]]) {
		Array array;
		for (id item in (NSArray *)p_value) {
			array.push_back(to_variant(item));
		}
		return array;
	}
	if ([p_value isKindOfClass:[NSDictionary class]]) {
		Dictionary dictionary;
		NSDictionary *source = p_value;
		for (id key in source) {
			dictionary[to_variant(key)] = to_variant(source[key]);
		}
		return dictionary;
	}
	return String::utf8([[p_value description] UTF8String]);
}

void GodotStoreKit::_bind_methods() {
	ClassDB::bind_method(D_METHOD("configure", "profile_id"), &GodotStoreKit::configure);
	ClassDB::bind_method(D_METHOD("request_products", "product_ids"), &GodotStoreKit::request_products);
	ClassDB::bind_method(D_METHOD("purchase", "product_id"), &GodotStoreKit::purchase);
	ClassDB::bind_method(D_METHOD("finish_transaction", "transaction_id"), &GodotStoreKit::finish_transaction);
	ClassDB::bind_method(D_METHOD("check_unfinished"), &GodotStoreKit::check_unfinished);

	ADD_SIGNAL(MethodInfo("products_received", PropertyInfo(Variant::ARRAY, "products"), PropertyInfo(Variant::ARRAY, "invalid_product_ids")));
	ADD_SIGNAL(MethodInfo("products_failed", PropertyInfo(Variant::STRING, "message")));
	ADD_SIGNAL(MethodInfo("purchase_completed", PropertyInfo(Variant::DICTIONARY, "transaction")));
	ADD_SIGNAL(MethodInfo("purchase_failed", PropertyInfo(Variant::STRING, "product_id"), PropertyInfo(Variant::STRING, "reason"), PropertyInfo(Variant::STRING, "message")));
	ADD_SIGNAL(MethodInfo("transaction_finished", PropertyInfo(Variant::STRING, "transaction_id")));
}

bool GodotStoreKit::configure(const String &p_profile_id) {
	return [bridge configureWithProfileId:to_ns_string(p_profile_id)];
}

void GodotStoreKit::request_products(const Array &p_product_ids) {
	NSMutableArray<NSString *> *ids = [NSMutableArray arrayWithCapacity:p_product_ids.size()];
	for (int i = 0; i < p_product_ids.size(); i++) {
		[ids addObject:to_ns_string(p_product_ids[i])];
	}
	[bridge requestProducts:ids];
}

void GodotStoreKit::purchase(const String &p_product_id) {
	[bridge purchase:to_ns_string(p_product_id)];
}

bool GodotStoreKit::finish_transaction(const String &p_transaction_id) {
	return [bridge finishTransaction:to_ns_string(p_transaction_id)];
}

void GodotStoreKit::check_unfinished() {
	[bridge checkUnfinished];
}

// Runs on the main thread. The signal is emitted deferred so the game handles it inside its own
// frame, as it does every other callback.
void GodotStoreKit::handle_event(const Dictionary &p_event) {
	const String type = p_event.get("type", "");
	if (type == "products") {
		call_deferred("emit_signal", "products_received", p_event.get("products", Array()), p_event.get("invalid_product_ids", Array()));
	} else if (type == "products_failed") {
		call_deferred("emit_signal", "products_failed", p_event.get("message", ""));
	} else if (type == "transaction") {
		call_deferred("emit_signal", "purchase_completed", p_event);
	} else if (type == "purchase_failed") {
		call_deferred("emit_signal", "purchase_failed", p_event.get("product_id", ""), p_event.get("reason", ""), p_event.get("message", ""));
	} else if (type == "transaction_finished") {
		call_deferred("emit_signal", "transaction_finished", p_event.get("transaction_id", ""));
	}
}

GodotStoreKit *GodotStoreKit::get_singleton() {
	return instance;
}

GodotStoreKit::GodotStoreKit() {
	ERR_FAIL_COND(instance != nullptr);
	instance = this;
	bridge = [[CRStoreKitBridge alloc] init];
	bridge.eventHandler = ^(NSDictionary<NSString *, id> *event) {
		if (GodotStoreKit::instance) {
			GodotStoreKit::instance->handle_event(to_variant(event));
		}
	};
}

GodotStoreKit::~GodotStoreKit() {
	bridge.eventHandler = nil;
	bridge = nil;
	instance = nullptr;
}
